test("debounce wywołuje ostatnią wartość dopiero po pełnej przerwie",()=>{vi.useFakeTimers();const fn=vi.fn<(text:string)=>void>(),run=debounce(fn,300);run("a");vi.advanceTimersByTime(200);run("ab");vi.advanceTimersByTime(299);expect(fn).not.toHaveBeenCalled();vi.advanceTimersByTime(1);expect(fn).toHaveBeenCalledTimes(1);expect(fn).toHaveBeenCalledWith("ab");});test("cancel usuwa oczekującą pracę",()=>{vi.useFakeTimers();const fn=vi.fn(),run=debounce(fn,100);run();run.cancel();vi.runAllTimers();expect(fn).not.toHaveBeenCalled();expect(vi.getTimerCount()).toBe(0);});test("dwie instancje nie anulują sobie timerów",()=>{vi.useFakeTimers();const a=vi.fn(),b=vi.fn(),first=debounce(a,100),second=debounce(b,100);first();second();first.cancel();vi.advanceTimersByTime(100);expect(a).not.toHaveBeenCalled();expect(b).toHaveBeenCalledTimes(1);});test("ustawienie daty nie odpala automatycznie timera",()=>{vi.useFakeTimers();vi.setSystemTime(new Date("2026-01-01T00:00:00Z"));const fn=vi.fn();setTimeout(fn,100);vi.setSystemTime(new Date("2027-01-01T00:00:00Z"));expect(fn).not.toHaveBeenCalled();vi.advanceTimersByTime(100);expect(fn).toHaveBeenCalledTimes(1);});test.each([-1,NaN,Infinity])("odrzuca opóźnienie %s",delay=>{expect(()=>debounce(()=>{},delay)).toThrow(RangeError);});

