import {expect,test} from "vitest";import {readFilters,patchFilters,listKey} from "./filters";
test("adres parsuje poprawny stan",()=>{expect(readFilters(new URLSearchParams("status=OPEN&q=api&sort=title%3Aasc&page=3"))).toEqual({status:"OPEN",q:"api",sort:"title:asc",page:3});});test("błędny adres ma przewidywalne domyślne wartości",()=>{expect(readFilters(new URLSearchParams("status=WRONG&sort=bad&page=-3"))).toEqual({status:null,q:"",sort:"createdAt:desc",page:1});});test("patch resetuje page, zachowuje obce klucze i wejście",()=>{const before=new URLSearchParams("q=api&page=3&utm=kurs"),after=patchFilters(before,{status:"OPEN"});expect(after.has("page")).toBe(false);expect(after.get("q")).toBe("api");expect(after.get("utm")).toBe("kurs");expect(before.get("page")).toBe("3");});test("cache ignoruje kolejność kluczy URL",()=>{expect(listKey(readFilters(new URLSearchParams("status=OPEN&page=2")))).toEqual(listKey(readFilters(new URLSearchParams("page=2&status=OPEN"))));});

