import {expect,test,vi} from "vitest";import {loadTitle} from "./loadTitle";
test("oczekuje na dane i przekazuje ID adapterowi",async()=>{const read=vi.fn().mockResolvedValue({id:42,title:"API"});await expect(loadTitle(42,read)).resolves.toBe("API");expect(read).toHaveBeenCalledExactlyOnceWith(42);});test("propaguje odrzucenie bez udawania sukcesu",async()=>{const error=Error("niedostępne"),read=vi.fn().mockRejectedValue(error);await expect(loadTitle(42,read)).rejects.toBe(error);});test("nie wywołuje adaptera dla błędnego ID",async()=>{const read=vi.fn();await expect(loadTitle(0,read)).rejects.toThrow(RangeError);expect(read).not.toHaveBeenCalled();});test("odrzuca dane innego rekordu",async()=>{await expect(loadTitle(42,vi.fn().mockResolvedValue({id:7,title:"Inny"}))).rejects.toThrow("Niepoprawny kontrakt");});test("odrzuca pusty tytuł",async()=>{await expect(loadTitle(42,vi.fn().mockResolvedValue({id:42,title:" "}))).rejects.toThrow("Niepoprawny kontrakt");});

