import {afterEach,expect,test,vi} from "vitest";afterEach(()=>vi.restoreAllMocks());
test("spyOn domyślnie obserwuje prawdziwą metodę",()=>{const target={sum:(a:number,b:number)=>a+b},spy=vi.spyOn(target,"sum");expect(target.sum(2,3)).toBe(5);expect(spy).toHaveBeenCalledWith(2,3);});test("mockClear usuwa historię, zachowuje implementację",()=>{const fn=vi.fn(()=>7);fn();fn.mockClear();expect(fn).not.toHaveBeenCalled();expect(fn()).toBe(7);});test("mockRestore przywraca metodę po zastąpieniu",()=>{const target={value:()=>5};const spy=vi.spyOn(target,"value").mockReturnValue(9);expect(target.value()).toBe(9);spy.mockRestore();expect(target.value()).toBe(5);});test("mockReturnValueOnce dotyczy jednego wywołania",()=>{const fn=vi.fn(()=>3).mockReturnValueOnce(8);expect([fn(),fn()]).toEqual([8,3]);});
